const agent = window.PolkaswapAgent ?? await new Promise((resolve) => window.addEventListener('polkaswap-agent-ready', (event) => resolve(event.detail.api), { once: true }));
const capabilities = agent.capabilities();
if (capabilities.version !== 'v1') throw new Error(`Unsupported PolkaswapAgent version: ${capabilities.version}`);
await agent.ready({ requireNode: true, timeoutMs: 30000 });

const status = agent.status();
if (!status.agent.mode) throw new Error(`Agent mode disabled; open with ?${status.agent.queryParam}=1 before the hash route.`);
if (!status.agent.disclaimerSuppressed) throw new Error('Agent disclaimer suppression is not active.');

const wallets = await agent.refreshWallets();
const wallet = wallets.find((item) => item.source === 'polkadot-js');
if (!wallet?.available) throw new Error('WALLET_NOT_FOUND');
const accounts = await agent.walletAccounts({ source: 'polkadot-js' });
await agent.connectWallet({ source: 'polkadot-js', address: accounts[0].address });
await agent.ready({ requireWallet: true, timeoutMs: 10000 });

const xor = await agent.resolveAsset({ asset: { symbol: 'XOR' }, includeBalance: true });
const pswap = await agent.resolveAsset({ asset: { symbol: 'PSWAP' }, includeBalance: true });
const assetIn = { address: xor.address };
const assetOut = { address: pswap.address };

const plan = await agent.planSwap({ assetIn: { symbol: 'XOR' }, assetOut: { symbol: 'PSWAP' }, amount: '1', side: 'input', dexId: 'best' });
if (plan.canExecute !== false || plan.requiresWallet !== false) throw new Error('Unexpected plan scope');
console.log(plan.quote.quoteDigest, plan.preview.args, plan.fees, plan.warnings, plan.expiresAt);
// This is SDK-call metadata, not a SCALE transaction or signing authorization.

const prepared = await agent.prepareSwap({ assetIn, assetOut, amount: '1', side: 'input' });
if (!prepared.canExecute || !prepared.revalidation.valid || prepared.warnings.some((warning) => warning.severity === 'critical')) throw new Error(prepared.warnings.map((warning) => warning.code).join(', ') || 'NOT_EXECUTABLE');
await agent.executeSwap({ intentId: prepared.intentId, clientOrderId: 'agent-swap-input-001' });

const prepared = await agent.prepareSwap({ assetIn, assetOut, amount: '100', side: 'output' });
if (!prepared.canExecute || !prepared.revalidation.valid) throw new Error(prepared.warnings.map((warning) => warning.code).join(', ') || 'NOT_EXECUTABLE');
await agent.executeSwap({ intentId: prepared.intentId, clientOrderId: 'agent-swap-output-001' });

const assessment = await agent.assessSwap({ assetIn, assetOut, amount: '1', maxPriceImpact: '3', requireCanExecute: true });
if (!assessment.approved) throw new Error(assessment.reasons.map((reason) => reason.code).join(', '));
await agent.executeSwap({ intentId: assessment.prepared.intentId, clientOrderId: 'agent-policy-swap-001' });

const prepared = await agent.prepareTransfer({ asset: assetIn, to: 'cn...', amount: '0.1' });
if (!prepared.canExecute || !prepared.revalidation.valid) throw new Error(prepared.warnings.map((warning) => warning.code).join(', ') || 'NOT_EXECUTABLE');
await agent.executeTransfer({ intentId: prepared.intentId, clientOrderId: 'agent-transfer-001' });

const prepared = await agent.prepareAddLiquidity({ assetA: assetIn, assetB: assetOut, amountA: '1' });
if (!prepared.canExecute || !prepared.revalidation.valid) throw new Error(prepared.warnings.map((warning) => warning.code).join(', ') || 'NOT_EXECUTABLE');
await agent.executeAddLiquidity({ intentId: prepared.intentId, clientOrderId: 'agent-lp-add-001' });

const positions = await agent.liquidityPositions({ assetA: assetIn, assetB: assetOut });
if (!positions.length) throw new Error('NO_LIQUIDITY_POSITION');
const request = { assetA: assetIn, assetB: assetOut, percent: '25' };
const prepared = await agent.prepareRemoveLiquidity(request);
if (!prepared.canExecute || !prepared.revalidation.valid) throw new Error(prepared.warnings.map((warning) => warning.code).join(', ') || 'NOT_EXECUTABLE');
await agent.executeRemoveLiquidity({ intentId: prepared.intentId, clientOrderId: 'agent-lp-remove-001' });

const maxTransfer = await agent.maxTransferAmount({ asset: assetIn });
const maxSwap = await agent.maxSwapInput({ assetIn, assetOut });
const maxLp = await agent.maxAddLiquidity({ assetA: assetIn, assetB: assetOut });
const maxRemove = await agent.maxRemoveLiquidity({ assetA: assetIn, assetB: assetOut });

const clientOrderId = 'agent-swap-input-001';
const local = agent.transactionStatus({ id: clientOrderId });
const status = local.source !== 'none' ? local : await agent.recoverTransaction({ clientOrderId, lookup: 'any' });
if (status.source === 'none') console.log('safe to prepare and execute again with the same clientOrderId');

const stopLocal = await agent.subscribeTransactions({ source: 'local', limit: 20, pollMs: 1000 }, (tx) => console.log(tx));
const stopIndexer = await agent.subscribeTransactions({ source: 'indexer', address: agent.status().wallet.address, includeExisting: true, limit: 20 }, (tx) => console.log(tx));
stopLocal();
stopIndexer();

const fullState = agent.exportState();
const auditState = agent.exportState({ redacted: true });
agent.importState({ state: fullState, merge: true });
agent.clearState({ clientOrderId: 'agent-swap-input-001' });

const client = await window.PolkaswapAgentClient.attach({ timeoutMs: 30000 });
await client.ready({ requireNode: true });
await client.prepareAndExecuteSwap({ assetIn, assetOut, amount: '1', side: 'input' }, { clientOrderId: 'client-swap-001' });
await client.prepareAndExecuteAddLiquidity({ assetA: assetIn, assetB: assetOut, amountA: '1' }, { clientOrderId: 'client-lp-add-001' });

try {
  await agent.ready({ requireWallet: true, timeoutMs: 10000 });
} catch (error) {
  if (error.code === 'WALLET_NOT_CONNECTED') console.log('connect wallet, then retry readiness');
  else if (error.code === 'NODE_NOT_READY') console.log('reload or switch endpoint');
  else throw error;
}
